-- Bronze table of the orders pipeline for the dev target.
-- Generated by the sp-dynamo-firehose-s3 skill. The bronze job writes to this
-- table but never creates it, so run this before the job's first run.
CREATE TABLE IF NOT EXISTS `dev`.`bronze`.`orders` (
  `data` VARIANT COMMENT "DynamoDB change event as delivered by Firehose from the table's Kinesis stream.",
  `_ingested_at` TIMESTAMP COMMENT "Time the bronze job loaded the record.",
  `_file_path` STRING COMMENT "S3 path of the Firehose file the record came from.",
  `_file_modification_time` TIMESTAMP COMMENT "Time the Firehose file the record came from was last modified in S3."
)
USING DELTA
COMMENT "Pipeline to ingest orders. Raw DynamoDB change events delivered by Firehose, one row per record, with ingestion and source file metadata.";
